import{_ as i,o as l,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Ceph Day CERN 2019: What’s New In Nautilus & Community News - Mike Perez","description":"","frontmatter":{"title":"Ceph Day CERN 2019: What’s New In Nautilus & Community News - Mike Perez","date":"2020-08-25T00:00:00.000Z","updated":"2020-08-26T00:00:00.000Z","tags":["Ceph社区","Nautilus版本更新","分布式存储","文档改进","Kubernetes集成"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Day_CERN_2019_-_What_s_New_In_Nautilus_Community_News_-_Mike_Perez.md","filePath":"posts/2020/Ceph_Day_CERN_2019_-_What_s_New_In_Nautilus_Community_News_-_Mike_Perez.md","lastUpdated":1780459816000}'),_={name:"posts/2020/Ceph_Day_CERN_2019_-_What_s_New_In_Nautilus_Community_News_-_Mike_Perez.md"};function s(o,e,r,u,n,p){return l(),t("div",null,[...e[0]||(e[0]=[a('<p>Ceph Day CERN 2019会议中，Mike Perez作为Red Hat开源项目办公室社区经理，介绍了Ceph社区的最新动态和Nautilus版本的更新。以下是会议关键内容的总结：</p><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>Mike Perez首先介绍了会议的背景，感谢Soft Iron和Western Digital的赞助以及CERN提供的场地。随后，他强调了Ceph基金会的成立及其重要性。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph基金会成立</strong>：</p><ul><li>八个月前，Ceph基金会在柏林成立，初始有31个成员，包括13个主要成员、10个一般成员和8个非营利及政府组织。</li><li>今年新增了两个一般成员和两个附属成员。</li><li>感谢Linux基金会在Ceph基金会成立和大型活动组织方面的支持。</li></ul></li><li><p><strong>文档改进</strong>：</p><ul><li>Ceph社区正在改进文档工具和流程，特别是通过DocuBetter项目。</li><li>每月第二个和第四个星期三举行会议，欢迎任何人参与。</li><li>Ceph基金会正在寻找一名专职的文档改进人员。</li></ul></li><li><p><strong>Ceph简介</strong>：</p><ul><li>Ceph是一个统一存储系统，提供S3和Swift兼容接口，支持块存储和符合POSIX的文件系统。</li><li>使用CRUSH算法确定数据位置，避免单点故障，支持复制和纠删码，强调数据安全和一致性。</li></ul></li><li><p><strong>Nautilus版本更新</strong>：</p><ul><li>Nautilus版本重点改进了易用性和管理功能。</li><li>引入了新的仪表盘，整合了多个分散的仪表盘项目，提供监控和管理功能。</li><li>推出了Orchestrator API，简化了Ceph的部署和管理。</li><li>新增了自动管理放置组数量和设备健康指标功能。</li></ul></li><li><p><strong>Kubernetes和Rook</strong>：</p><ul><li>Ceph社区关注Kubernetes集成，通过Rook项目简化Ceph在Kubernetes中的部署和管理。</li><li>Rook是一个强大的Ceph操作器，支持声明式资源定义，简化集群管理。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>Ceph基金会将继续支持社区发展，特别是文档和易用性的改进。</li><li>将继续推动Ceph与Kubernetes的集成，通过Rook等项目简化部署。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>推进DocuBetter项目，改进Ceph文档和工具。</li><li>招聘专职的文档改进人员。</li><li>加强与Kubernetes社区的合作，推动Rook等项目的发展。</li><li>继续开发和优化Nautilus版本的功能。</li></ul>',9)])])}const N=i(_,[["render",s]]);export{C as __pageData,N as default};
